#!ibl edition=2
$ai = "/Users/kangkukjin/Desktop/AI/indiebizOS/outputs/long_sentence_imagination/2026-10-08_36회차/ai"
$src = f"${$ai}/source"
$base = f"${$ai}/base"
$pres = f"${$ai}/presentation"
$rec = f"${$ai}/recovery"
$top = [self:list]{path:$ai} >> [table:each]{return $it.name}
assert not contains($top, "recovery") or len([self:list]{path:$rec}) == 0, "recovery 폴더가 이미 비어 있지 않음"
$vtext = [self:read]{path:f"${$base}/work/verify_zip.py"}
$vf = [self:write]{path:"~turn/verify_zip.py", content:$vtext.text}
$pre_src = [self:script]{path:$vf.path, args:{op:"hash", src:$src}}
$pre_base = [self:script]{path:$vf.path, args:{op:"hash", src:$base}}
$pre_pres = [self:script]{path:$vf.path, args:{op:"hash", src:$pres}}
$old = [self:read]{path:f"${$base}/result.json"}
$cat = [self:read]{path:f"${$src}/catalog.json"}
$names = $pre_src.files >> [table:each]{return $it.rel}
[def:찾기]($kits,$id){ return ($kits >> [table:filter]{where:($k)=>$k.id==$id})[0] }
$g = [fn:찾기]{kits:$cat.data.kits, id:"gamma"}
$gold = [fn:찾기]{kits:$old.data.kits, id:"gamma"}
assert $g.files == $gold.files, "gamma 필요 목록이 직전 결과와 다름"
$gmiss = difference($g.files, $names)
assert len($gmiss) == 0, "gamma 여전히 누락", {missing:$gmiss}
[self:mkdir]{path:$rec}
$gzip = f"${$rec}/gamma.zip"
$gabs = $g.files >> [table:each]{return f"${$src}/${$it}"}
$pack = [self:script]{op:"run", id:"압축", args:{op:"pack", paths:$gabs, base:$src, output:$gzip, exclude:[], overwrite:false}}
$vg = [self:script]{path:$vf.path, args:{op:"verify", zip:$gzip, src:$src, files:$g.files}}
assert $vg.ok, "gamma ZIP 대조 실패", {verify:$vg}
$prev = ["beta","alpha"] >> [table:each]{
  $k = [fn:찾기]{kits:$old.data.kits, id:$it}
  $v = [self:script]{path:$vf.path, args:{op:"verify", zip:$k.archive, src:$src, files:$k.files}}
  assert $v.ok and $v.verified_count == $k.verified_count, f"${$it} 기존 ZIP 재대조 실패", {verify:$v}
  return {kit:$k, check:$v}
}
$gkit = {id:"gamma", status:"ready", archive:$gzip, files:$g.files, missing:[], verified_count:$vg.verified_count}
$kits = [$gkit, $prev[0].kit, $prev[1].kit]
$result = {title:"교육 자료 최종 인계", kits:$kits}
$rows = $kits >> [table:each]{return f"| ${$it.id} | ${$it.status} | ${len($it.files)} | ${$it.verified_count} | ${len($it.missing)==0 ? "없음" : join(", ", $it.missing)} | ${$it.archive} |"}
$md = f"""# 교육 자료 최종 인계

| 반 | 상태 | 필요 수 | 검증 수 | 누락 | ZIP 경로 |
|---|---|---|---|---|---|
${join("\n", $rows)}

- 이 문서는 앞 인계(base/result.json)를 이어받아, 보충된 source/gamma/lesson07.txt로 막혔던 gamma 반만 새로 준비한 완결판이다.
- gamma: source/catalog.json의 필요 목록 ${len($g.files)}개로 등록 스크립트 `압축`(op:pack, base=source)을 써서 recovery/gamma.zip을 새로 만들었다.
- alpha·beta: 기존 ZIP(base 폴더)을 재생성·복사·덮어쓰기 하지 않았다. 경로·상태·필요 목록·누락·검증 수는 base/result.json 값 그대로다.
- 검증(이번 실행, 세 반 전건): ZIP을 열어 항목 이름 집합 = 필요 목록, 중복 0, 디렉터리 항목 0, CRC 이상 없음, 항목별 바이트·sha256 = 현재 source 원본을 확인했다(base/work/verify_zip.py와 같은 코드).
- 필요 파일 전체 목록은 같은 폴더의 result.json kits[].files에 있다.
"""
$wj = [self:write]{path:f"${$rec}/result.json", content:json($result)}
$wm = [self:write]{path:f"${$rec}/report.md", content:$md}
$rj = [self:read]{path:f"${$rec}/result.json"}
$rm = [self:read]{path:f"${$rec}/report.md"}
$post_src = [self:script]{path:$vf.path, args:{op:"hash", src:$src}}
$post_base = [self:script]{path:$vf.path, args:{op:"hash", src:$base}}
$post_pres = [self:script]{path:$vf.path, args:{op:"hash", src:$pres}}
$reread_ok = $rj.data == $result and $rm.text == $md
assert $reread_ok, "재독 불일치"
assert $pre_src.digest == $post_src.digest and $pre_base.digest == $post_base.digest and $pre_pres.digest == $post_pres.digest, "보존 대상 변경 감지"
$same_prev = $prev >> [table:each]{
  $o = [fn:찾기]{kits:$old.data.kits, id:$it.kit.id}
  $n = [fn:찾기]{kits:$rj.data.kits, id:$it.kit.id}
  return {id:$o.id, same:$o == $n}
}
return {order:$rj.data.kits >> [table:each]{return $it.id}, title:$rj.data.title,
  gamma:{need:len($g.files), has_lesson07:contains($g.files,"gamma/lesson07.txt"), verify:$vg},
  prev_checks:$prev >> [table:each]{return {id:$it.kit.id, ok:$it.check.ok, verified:$it.check.verified_count, entries:$it.check.entries}},
  same_prev:$same_prev, reread_ok:$reread_ok,
  digests:{src:$pre_src.digest==$post_src.digest, base:$pre_base.digest==$post_base.digest, pres:$pre_pres.digest==$post_pres.digest},
  source_files:len($pre_src.files), recovery:[self:list]{path:$rec} >> [table:select]{columns:["name","size"]}, report:$rm.text}

